function term_mul(g, a, h, b):
    result_mono <- empty map
    for each height k in keys(g) union keys(h):
        v <- g.get(k,0) + h.get(k,0)      # value-group addition
        if v != 0: result_mono[k] <- v
    return (result_mono, a * b)           # coefficients multiply

